package net.juspay.xynespaces.integrity

import android.app.Activity
import android.graphics.Color
import android.os.Bundle
import android.util.TypedValue
import android.view.Gravity
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.TextView

/**
 * Terminal screen shown when [IntegrityGuard] detects a tampered or untrusted build.
 *
 * The UI is built in code on purpose: `android/app/src/main/res/` is regenerated by
 * `expo prebuild`, so shipping a layout XML through the config plugin would add a second
 * generated-file surface for no benefit.
 *
 * There is no path forward from here — back and recents are no-ops, and finishing tears down
 * the whole task rather than returning to MainActivity.
 */
class TamperBlockActivity : Activity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(buildView())
    }

    private fun buildView(): ViewGroup {
        val density = resources.displayMetrics.density
        fun dp(value: Int) = (value * density).toInt()

        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setBackgroundColor(Color.WHITE)
            setPadding(dp(32), dp(32), dp(32), dp(32))
            layoutParams = ViewGroup.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT,
            )
        }

        val title = TextView(this).apply {
            text = "Xyne Spaces cannot run"
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 20f)
            setTextColor(Color.parseColor("#1C1F23"))
            gravity = Gravity.CENTER
        }

        val body = TextView(this).apply {
            text =
                "This copy of the app has been modified or was installed from an untrusted " +
                    "source. For your security it will not start.\n\n" +
                    "Please reinstall Xyne Spaces from the Google Play Store."
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 15f)
            setTextColor(Color.parseColor("#545C66"))
            gravity = Gravity.CENTER
            setPadding(0, dp(16), 0, 0)
        }

        root.addView(title)
        root.addView(body)
        return root
    }

    @Suppress("OVERRIDE_DEPRECATION", "MissingSuperCall")
    override fun onBackPressed() {
        // Intentionally inert: this screen is terminal, and the user must not be able to
        // dismiss it back into the app. IntegrityGuard already cleared the task before
        // launching it, so there is nothing behind this activity to return to.
    }
}
